@media(max-width:600px){.settings-hero{padding:20px;border-radius:16px}.settings-hero-icon{width:46px;height:46px;flex-basis:46px;border-radius:13px;font-size:19px}.settings-fields{grid-template-columns:1fr;padding:14px;gap:14px}.settings-card-head{padding:14px}.settings-search{gap:7px;padding:7px 10px}.settings-search span{display:none}.settings-savebar{bottom:5px;padding:10px}.settings-savebar>div{width:100%;margin:0 0 4px}.settings-savebar .btn{flex:1;font-size:12px;padding:9px 8px}.settings-rail-card{grid-template-columns:1fr;padding:14px}.settings-rail-card>a{grid-column:1/-1}}
</style>
<script>
document.addEventListener('DOMContentLoaded',()=>{const search=document.getElementById('settingsSearch'),count=document.getElementById('settingsCount'),fields=[...document.querySelectorAll('[data-settings-field]')],cards=[...document.querySelectorAll('[data-settings-section]')];const filter=()=>{const q=(search.value||'').trim().toLocaleLowerCase('bn');let shown=0;fields.forEach(f=>{const match=!q||(f.dataset.search||'').toLocaleLowerCase('bn').includes(q);f.hidden=!match;if(match)shown++;});cards.forEach(c=>{c.hidden=!c.querySelector('[data-settings-field]:not([hidden])')});count.textContent=q?shown+'টি সেটিংস মিলেছে':'সব '+fields.length+'টি সেটিংস';};search?.addEventListener('input',filter);const select=document.getElementById('hero_image'),preview=document.getElementById('heroImagePreview');if(select&&preview)select.addEventListener('change',()=>preview.src='../../'+select.value);document.getElementById('siteSettingsForm')?.addEventListener('submit',()=>{const b=document.querySelector('.settings-savebar button[type="submit"]');if(b){b.disabled=true;b.innerHTML='<i class="fa-solid fa-spinner fa-spin me-1"></i> সংরক্ষণ হচ্ছে…';}});});
</script>
